-- Mutable run selection is separate from immutable route configuration.
CREATE TABLE dungeon_difficulty_selections (
 instance_id bigint PRIMARY KEY REFERENCES dungeon_instances(instance_id),
 stasis_level integer NOT NULL CHECK(stasis_level BETWEEN 1 AND 10),
 competitive boolean NOT NULL DEFAULT false,
 competitive_max_level integer NOT NULL DEFAULT 0 CHECK(competitive_max_level BETWEEN 0 AND 230),
 revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),
 selected_by bigint REFERENCES characters(id),
 updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(competitive=(competitive_max_level>0))
);
CREATE TABLE dungeon_encounter_difficulties (
 fight_id integer PRIMARY KEY REFERENCES dungeon_room_encounters(fight_id),
 instance_id bigint NOT NULL REFERENCES dungeon_instances(instance_id),
 selection_revision bigint NOT NULL,
 snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'),
 created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE FUNCTION reject_dungeon_encounter_difficulty_mutation()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'dungeon encounter difficulty snapshots are immutable'; END;
$$;
CREATE TRIGGER dungeon_encounter_difficulty_immutable
BEFORE UPDATE OR DELETE ON dungeon_encounter_difficulties
FOR EACH ROW EXECUTE FUNCTION reject_dungeon_encounter_difficulty_mutation();

